pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // General rule: for ANY actor, ANY positive amount and ANY admissible lock time,
    // once a valid log sink has been configured via SetLogFile, calling Put must NOT revert.
    function testFuzz_property(uint256 amount, address actor, uint256 lockTime) public {
        vm.assume(actor != address(0) && actor != address(c));
        vm.assume(amount > 0);
        bound(lockTime, 0, type(uint256).max / 4);

        // environment: a working logger contract passed to SetLogFile
        LogSink sink = new LogSink();
        c.SetLogFile(address(sink));

        vm.deal(actor, amount);
        vm.prank(actor);
        bool ok;
        try c.Put{value: amount}(lockTime) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok, "Put must not revert when a valid LogFile was set");
    }
}

// minimal working logger used as the (admissible) external counterparty
contract LogSink {
    function AddMessage(address, uint256, string memory) external pure {}
}

