pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    LogSpy spy;

    function setUp() public { c = new C(); spy = new LogSpy(); }

    function testFuzz_property(address logAddr, address actor, uint256 amount) public {
        vm.assume(logAddr != address(0));
        vm.assume(actor != address(0));
        amount = bound(amount, 1, 10 ether);

        vm.prank(actor);
        c.SetLogFile(logAddr);

        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(0);

        assertTrue(spy.lastSender() == actor && keccak256(bytes(spy.lastData())) == keccak256(bytes("Put")), "Put must log the message on the supplied log address");
    }
}

contract LogSpy {
    address public lastSender;
    string public lastData;
    function AddMessage(address _adr, uint256 _val, string calldata _data) external {
        lastSender = _adr;
        lastData = _data;
    }
    receive() external payable {}
    fallback() external {}
}

