        vm.assume(logAddr != address(c));
        vm.assume(logAddr.code.length == 0);
        vm.assume(actor != address(c));
        vm.assume(actor.code.length == 0);
        amount = bound(amount, 1, 1e30);

        c.SetLogFile(logAddr);

        vm.deal(actor, amount);
        vm.prank(actor);
        try c.Put{value: amount}(0) {
            assertTrue(true);
        } catch {
            assertTrue(false);
        }
    }
}

