contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint v, uint am) public payable {
        require(v > 0);
        // initialize Log so Collect can log without reverting (allowed pre-initialization in both versions)
        c.SetLogFile(address(this));
        // In P this sets MinSum = v; in M it reverts before initialization.
        c.SetMinSum(v);
        // A Collect call must never change MinSum away from v.
        c.Collect(am);
        assert(c.MinSum() == v);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint v) public payable {
        require(v > 0);
        (bool s, ) = address(c).call(abi.encodeWithSignature("SetMinSum(uint256)", v));
        s; // on P this succeeds (not yet initialized); on M it reverts and is caught
        c.Collect(v);
        assert(c.MinSum() == v);
    }
    receive() external payable {}
}
